// PROBLEM: Given an array of integers, return the indices of the
// two numbers that add up to a target sum.

// U - UNDERSTAND:
// 'Let me make sure I understand: I'm given [2, 7, 11, 15]
//  and target=9, and I should return [0, 1] because nums[0]+nums[1]=9?
//  Is there guaranteed to be exactly one solution? Can the same
//  element be used twice? What if the array is empty?'

// T - TEST CASES:
// [2, 7, 11, 15], target=9  ->  [0, 1]  (basic case)
// [3, 3], target=6           ->  [0, 1]  (same value, different index)
// [1], target=2              ->  []      (empty - edge case)

// T - THINK ALOUD:
// 'Naive approach: O(n^2) nested loop checking all pairs. That works
//  but I can do better. If I store what I've seen in a Map, I can
//  check in O(1) whether the complement exists. Let me try that -
//  for each number, I check if (target - number) is already in the
//  map. If yes, I have my pair. O(n) time, O(n) space.'

// E - EXECUTE:
function twoSum(nums: number[], target: number): number[] {
  const seen = new Map<number, number>(); // value -> index

  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];

    if (seen.has(complement)) {
      return [seen.get(complement)!, i];
    }

    seen.set(nums[i], i);
  }

  return []; // no solution found
}

// R - REVIEW:
// 'Let me trace through [3,3], target=6:
//  i=0: complement=3, not in map, add 3->0 to map
//  i=1: complement=3, IS in map at index 0, return [0,1] ✓
// Time: O(n) - single pass. Space: O(n) - the map.
// Edge case [1] with target=2: complement=1, not in map, loop ends,
// return [] correctly.'

