// PROBLEM 2: Given an array of integers, find if there is a
// contiguous subarray whose sum equals a target k.
// Example: [1, 2, 3], k=5 -> true (subarray [2,3])
//          [1, 2, 3], k=7 -> false

// Write out all 5 UTTER steps for Problem 2:

codingChallenge.solutionExample:
// PROBLEM 1: First Non-Repeating Character

// U - UNDERSTAND:
// - 'Is input always lowercase ASCII, or Unicode?'
// - 'Can input be empty string?'
// - 'If multiple non-repeating chars, return first occurrence index?'

// T - TEST CASES:
// 'leetcode' -> 0 (l appears once; e, t, c, o, d also appear once
//                  but l is first by index)
// 'aabb'    -> -1  (both a and b repeat)
// ''        -> -1  (edge: empty string)
// 'z'       -> 0   (edge: single character)

// T - THINK ALOUD:
// 'I need to know how many times each character appears, then find
// the first character with count 1. I can do this in two passes:
// first build a frequency Map, then iterate the string again to
// find the first char with frequency 1. O(n) time, O(26) = O(1) space
// (assuming lowercase ASCII - I'd clarify this first).'

// E - EXECUTE:
function firstUniqChar(s: string): number {
  const freq = new Map<string, number>();
  for (const ch of s) freq.set(ch, (freq.get(ch) ?? 0) + 1);
  for (let i = 0; i < s.length; i++) {
    if (freq.get(s[i]) === 1) return i;
  }
  return -1;
}

// R - REVIEW:
// Trace 'leetcode': freq={l:1,e:3,t:1,c:1,o:1,d:1}
// i=0: l has freq 1 -> return 0 ✓
// Trace 'aabb': freq={a:2,b:2} -> loop ends -> return -1 ✓
// Time: O(n) two passes. Space: O(1) (bounded character set).

// ---

// PROBLEM 2: Subarray Sum Equals K

// U - UNDERSTAND:
// - 'Can integers be negative?'
// - 'Can k be 0?'
// - 'Contiguous subarray only, not any subsequence?'

// T - TEST CASES:
// [1,2,3], k=5 -> true ([2,3])
// [1,2,3], k=7 -> false
// [-1,2,3], k=2 -> true ([-1,2,3] or [2])
// [1], k=1     -> true

// T - THINK ALOUD:
// 'Sliding window won't work with negatives (can't know whether to
// expand or shrink). I'll use prefix sums: prefixSum[i] = sum of
// first i elements. Subarray [i..j] has sum = prefixSum[j] - prefixSum[i].
// If prefixSum[j] - prefixSum[i] = k, then prefixSum[i] = prefixSum[j]-k.
// Use a Map to store seen prefix sums. O(n) time, O(n) space.'

// E - EXECUTE:
function subarraySum(nums: number[], k: number): boolean {
  const prefixSums = new Map<number, boolean>();
  prefixSums.set(0, true); // empty prefix
  let sum = 0;
  for (const num of nums) {
    sum += num;
    if (prefixSums.has(sum - k)) return true;
    prefixSums.set(sum, true);
  }
  return false;
}

// R - REVIEW:
// [1,2,3] k=5: sum=1, check -4(no); sum=3, check -2(no);
// sum=6, check 1(yes!) -> true ✓
// Time: O(n). Space: O(n).

